local KTool = CS.Engine.Lib.KTool
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")

local cs_coroutine = require("XLua.cs_coroutine")
--- from:  > name: Cell
---@class OverseaMallFurnitureDialogCell
---@field Env                           	OverseaMallFurnitureDialogCell          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Root                          	UnityEngine.RectTransform               
---@field ImgFurniture1                 	UnityEngine.RectTransform               
---@field ImgFurniture2                 	UnityEngine.RectTransform               
---@field TextName                      	UnityEngine.RectTransform               
---@field BtnCheck                      	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
---@field Page                          	UnityEngine.RectTransform               
---@field ImgPage                       	UnityEngine.RectTransform               
---@field Countdown                     	UnityEngine.RectTransform               
---@field TextTime                      	UnityEngine.RectTransform               
---@field BtnCurrencyPurchase           	UnityEngine.RectTransform               
---@field BtnDirectPurchase             	UnityEngine.RectTransform               
---@field Finish                        	UnityEngine.RectTransform               
---@field OriginalPrice                 	Engine.Modules.LuaBehaviour             
---@field NowPrice                      	Engine.Modules.LuaBehaviour             
---@field DirectOriginalPrice           	UnityEngine.RectTransform               
---@field DirectNowPrice                	UnityEngine.RectTransform               
local OverseaMallFurnitureDialogCell = Class('OverseaMallFurnitureDialogCell')
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
local CurryEnvPath = "Game.Behaviours.CommonCurrencyNode"

function OverseaMallFurnitureDialogCell:__init()

end

function OverseaMallFurnitureDialogCell:__delete()
    self.isStart = nil
    self.pageIndex = nil
    self.curNodeIndex = nil
    self.index = nil
end

function OverseaMallFurnitureDialogCell:Awake()
    SetButtonAction(self.BtnCheck,Bind(self,self.OnBtnCheckClick))
    SetButtonAction(self.Root,Bind(self,self.OnImageChangeClick))
    SetButtonAction(self.BtnDirectPurchase,Bind(self,self.OnBtnDirectPurchaseClick))
    SetButtonAction(self.BtnCurrencyPurchase,Bind(self,self.OnBtnCurrencyPurchaseClick))
    self:InitEnv()

    self.onBuySuccessEvent = Events.AddListener(Constants.EventNames.OverseaMallRenovateBuySuccess,Bind(self,self.OnBuySuccess))
end

function OverseaMallFurnitureDialogCell:InitEnv()
    if self.OriginalPrice then
        local env = CfUtils.GetLuaScr(self.OriginalPrice,CurryEnvPath)
        if env then
            self.originalPriceEnv = env
        end
    end

    if self.NowPrice then
        local env = CfUtils.GetLuaScr(self.NowPrice,CurryEnvPath)
        if env then
            self.nowPriceEnv = env
        end
    end
end


function OverseaMallFurnitureDialogCell:OnDisable()
    self.isStart = false

    self:RemoveCo()
    self:RemoveTimer()
    if not isNull(self.cachePage) then
        for i, v in pairs(self.cachePage) do
            CfUtils.SafeDelete(v.gameObject)
        end
        self.cachePage = nil
    end

    if self.onBuySuccessEvent then
       Events.RemoveListener(Constants.EventNames.OverseaMallRenovateBuySuccess,self.onBuySuccessEvent)
        self.onBuySuccessEvent = nil
    end
end

function OverseaMallFurnitureDialogCell:RemoveCo()
    if not isNull(self.showCo) then
        cs_coroutine.stop(self.showCo)
        self.showCo = nil
    end
end

function OverseaMallFurnitureDialogCell:RefreshShow(data)
    self.data = data
    self:InitPageNode()
    self:RefreshInfo()
    self:RemoveCo()
    self:StartShowAni()
end

function OverseaMallFurnitureDialogCell:OnBuySuccess()
    KTool.SetActive(self.BtnCurrencyPurchase.gameObject,false)
    KTool.SetActive(self.BtnDirectPurchase.gameObject,false)
    KTool.SetActive(self.Finish.gameObject,true)
end

function OverseaMallFurnitureDialogCell:RefreshInfo()
    local suitVo = MaidCoffeeUtils.GetSuitRenovateVo(self.data.avatarSuitId)
    CfUtils.FillText(self.TextName,suitVo.name)

    local num = MaidCoffeeUtils.GetSuitAestheticsValue(suitVo.furnitureIds)
    CfUtils.FillText(self.TextNumber, num)

    self:StartCountDown()

    local isHave = MaidCoffeeUtils.IsHaveCattySuitBySuitId(self.data.avatarSuitId)
    KTool.SetActive(self.Finish.gameObject,isHave)

    if isHave then
        KTool.SetActive(self.BtnCurrencyPurchase.gameObject,false)
        KTool.SetActive(self.BtnDirectPurchase.gameObject,false)
    else
        local isDirect = (not next(self.data.prices))
        KTool.SetActive(self.BtnCurrencyPurchase.gameObject,not isDirect)
        KTool.SetActive(self.BtnDirectPurchase.gameObject,isDirect)
        if isDirect then
            CfUtils.FillText(self.DirectOriginalPrice, CfUtils.GetCustomDisplayPrice(self.data.original, nil, 24))
            local windowPricesId = CfUtils.GetWindowsPriceId(self.data)
            CfUtils.FillText(self.DirectNowPrice, CfUtils.GetCustomDisplayPrice(windowPricesId, self.data.channelProductId, 24))
        else
            local goodId = self.data.prices[1].currency
            self.originalPriceEnv:SetCurrencyShow(goodId ,self.data.prices[1].original)
            self.nowPriceEnv:SetCurrencyShow(goodId ,self.data.prices[1].current)
        end
    end
end

function OverseaMallFurnitureDialogCell:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

function OverseaMallFurnitureDialogCell:OnBtnDirectPurchaseClick()
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaMallRenovaDialog,parameters = {data = self.data,cb = function()
        self:OnBuySuccess()
    end}})
end

function OverseaMallFurnitureDialogCell:OnBtnCurrencyPurchaseClick()
    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaMallRenovaDialog,parameters = {data = self.data,cb = function()
        self:OnBuySuccess()
    end}})
end


function OverseaMallFurnitureDialogCell:StartCountDown()
    local remainTime = self.data.remainTime
    CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(remainTime)))
    self:RemoveTimer()
    if remainTime > 0 then
        self.isTimeOver = false
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(count)))
            else
                CfUtils.FillText(self.TextTime,CfUtils.GetTimeHMS10(checkNumber(0)))
                CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
                self.isTimeOver = true
                self.Timer = nil
            end
        end, remainTime + 1, false, true)
    end
end

function OverseaMallFurnitureDialogCell:InitPageNode()
    KTool.SetActive(self.ImgPage.gameObject,true)
    CfUtils.SetUISwitchImage(self.ImgPage,1)

    local count = self:GetMaxCount()
    self.cachePage = {}
    for i = 1, count do
        if i > self.Page.transform.childCount then
            local pageNode = CS.UnityEngine.GameObject.Instantiate(self.ImgPage.gameObject)
            KTool.SetParent(pageNode,self.Page.gameObject,false)
            KTool.SetActive(pageNode.gameObject,true)
            table.insert(self.cachePage,pageNode)
        end
    end
end

function OverseaMallFurnitureDialogCell:GetMaxCount()
    return self.data.furniturePictureNum
end


function OverseaMallFurnitureDialogCell:OnBtnCheckClick()
    local screenId = CS.Engine.UI.UIModule.CurrentScreen.Argument.id
    ---如果是从装修直接 进来的商店  这时候 点按钮  直接 返回
    if screenId == Constants.UITypeIds.UIMaidCoffeeEnterScene then
        CS.Engine.UI.UIModule.BackDialog()
    else
        GameUtils.Request(Interfaces.MaidCoffeeHome, {}, function(req, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local data = checkTable(response.data)
            ---@type MaidCoffeeComponent
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            component:InitialDojo(data)

            local MaidCoffeeDriver = import("Game.MaidCoffee.MaidCoffeeDriver")
            local opDriver = MaidCoffeeDriver.New()
            opDriver:Start({ id = Constants.UITypeIds.OverseaRenovaMainDialog, data = self.data})
        end)
    end
end

function OverseaMallFurnitureDialogCell:OnImageChangeClick()
    self.isStart = false
    self:RemoveCo()

    if self.pageIndex + 1 > self:GetMaxCount() then
        self.pageIndex = 1
    else
        self.pageIndex = self.pageIndex + 1
    end
    self:SetPageImage(self.pageIndex)
    if self.index == 1 then
        CfUtils.PlayAnimation(self.Root,"OverseaMallFurnitureDialog_CellChange_Img1ToImg2")
        self.index = 2
    else
        CfUtils.PlayAnimation(self.Root,"OverseaMallFurnitureDialog_CellChange_Img2ToImg1")
        self.index = 1
    end
    self.isStart = true
    self:StartAni()
end


function OverseaMallFurnitureDialogCell:StartShowAni()
    self.isStart = true
    self.index = 1
    self.pageIndex = 1
    self:StartAni()
end

function OverseaMallFurnitureDialogCell:StartAni()
    local maxCount = self:GetMaxCount()
    self:RemoveCo()
    self.showCo = cs_coroutine.start(function()
        while(self.isStart) do
            self:SetPageImage(self.pageIndex)
            if self.index == 1 then
                coroutine.yield(CS.UnityEngine.WaitForSeconds(3))
                CfUtils.PlayAnimation(self.Root,"OverseaMallFurnitureDialog_CellChange_Img1ToImg2")
                self.index = self.index + 1
            elseif self.index == 2 then
                coroutine.yield(CS.UnityEngine.WaitForSeconds(3))
                CfUtils.PlayAnimation(self.Root,"OverseaMallFurnitureDialog_CellChange_Img2ToImg1")
                self.index = 1
            end

            self.pageIndex = self.pageIndex + 1
            if self.pageIndex > maxCount then
                self.pageIndex = 1
            end
        end
    end)
end

function OverseaMallFurnitureDialogCell:SetPageImage(pageIndex)
    local imagePath = OverseaStoreConstants.ImgPath.BattleBgPath
    local name2 = string.format("%s_%s",self.data.furniturePicture,pageIndex)
    local path = string.format(imagePath,name2)
    if self.index % 2 == 0 then
        CfUtils.FillImage(self.ImgFurniture2,path)
    else
        CfUtils.FillImage(self.ImgFurniture1,path)
    end

    if not isNull(self.curNodeIndex) then
        local node = self.Page.transform:GetChild(self.curNodeIndex - 1)
        CfUtils.SetUISwitchImage(node,1)
    end

    self.curNodeIndex = pageIndex
    local node = self.Page.transform:GetChild(self.curNodeIndex - 1)
    if not isNull(node) then
        CfUtils.SetUISwitchImage(node,2)
    end
end

function OverseaMallFurnitureDialogCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaMallFurnitureDialogCell